-- [⚠공유 7화면(그리드메타)] EndCustomer  (사내 LAST_UPDATE=2026-08-18)
MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING DUAL ON (T.SQL_ID = 'EndCustomer' AND T.MDU_DIVS_CD = 'DM')
WHEN MATCHED THEN UPDATE SET T.SQL_NM = 'EndCustomer', T.SQL_DTL_CTN = 'SELECT DISTINCT A.DIVISION_ID, B.DEPT_ID,        CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE             ELSE A.END_CUSTOMER        END AS CODE,        NVL(D.SEGMENT3, CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE                             ELSE A.END_CUSTOMER                        END) AS NAME FROM SCM_MGR.SCM_MST_SITE A LEFT OUTER JOIN SCM_MGR.SCM_MST_SITE_ITEM B              ON A.DIVISION_ID = B.DIVISION_ID             AND A.SCM_SITE_ID = B.SCM_SITE_ID LEFT OUTER JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D              ON A.DIVISION_ID = D.SEGMENT1             AND A.END_CUSTOMER = D.SEGMENT2             AND D.LOOKUP_TYPE = ''END_CUSTOMER''             AND D.VALID_YN = ''Y'' WHERE A.DIVISION_ID IN (     SELECT DISTINCT UNIT_ID AS DIVISION_ID     FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M     WHERE USER_ID = @sesUserId       AND UNIT_TP_CD = ''D'' ) AND A.END_CUSTOMER IS NOT NULL ORDER BY DIVISION_ID, NAME, CODE', T.USE_YN = 'Y', T.CREATED_BY = 'SYSTEM', T.CREATION_DATE = TO_DATE('20260213120525','YYYYMMDDHH24MISS'), T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = TO_DATE('20260818163403','YYYYMMDDHH24MISS')
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('EndCustomer', 'DM', 'EndCustomer', 'SELECT DISTINCT A.DIVISION_ID, B.DEPT_ID,        CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE             ELSE A.END_CUSTOMER        END AS CODE,        NVL(D.SEGMENT3, CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE                             ELSE A.END_CUSTOMER                        END) AS NAME FROM SCM_MGR.SCM_MST_SITE A LEFT OUTER JOIN SCM_MGR.SCM_MST_SITE_ITEM B              ON A.DIVISION_ID = B.DIVISION_ID             AND A.SCM_SITE_ID = B.SCM_SITE_ID LEFT OUTER JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D              ON A.DIVISION_ID = D.SEGMENT1             AND A.END_CUSTOMER = D.SEGMENT2             AND D.LOOKUP_TYPE = ''END_CUSTOMER''             AND D.VALID_YN = ''Y'' WHERE A.DIVISION_ID IN (     SELECT DISTINCT UNIT_ID AS DIVISION_ID     FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M     WHERE USER_ID = @sesUserId       AND UNIT_TP_CD = ''D'' ) AND A.END_CUSTOMER IS NOT NULL ORDER BY DIVISION_ID, NAME, CODE', 'Y', 'SYSTEM', TO_DATE('20260213120525','YYYYMMDDHH24MISS'), 'admin', TO_DATE('20260818163403','YYYYMMDDHH24MISS'));

-- [전용(그리드메타 기준) / ⚠FE 타소비처: mkt-fcst, project-list, project-master, sales-plan-waterfall, SearchFields] EndCustomerByDivision  (사내 LAST_UPDATE=2026-07-23)
MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T
USING DUAL ON (T.SQL_ID = 'EndCustomerByDivision' AND T.MDU_DIVS_CD = 'DM')
WHEN MATCHED THEN UPDATE SET T.SQL_NM = 'DMF0003 EndCustomerByDivision (AS-IS BigFilter/UP_FX 1:1)', T.SQL_DTL_CTN = 'SELECT DIVISION_ID, DEPT_ID, CODE, NAME FROM ('||CHR(10)||'SELECT DISTINCT A.DIVISION_ID, B.DEPT_ID, A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME'||CHR(10)||'FROM SCM_MST_SITE_ITEM A'||CHR(10)||'JOIN SCM_MST_SSO_USER_INFO B ON B.USER_ID = TRIM(REGEXP_SUBSTR(A.OWNER, ''[^,]+'', 1, 1))'||CHR(10)||'JOIN SCM_MST_SSO_DEPT_INFO C ON B.DEPT_ID = C.DEPT_ID'||CHR(10)||'LEFT JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D'||CHR(10)||'  ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'''||CHR(10)||'WHERE A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y'''||CHR(10)||'UNION'||CHR(10)||'SELECT L.SEGMENT1, NULL, L.SEGMENT2, L.SEGMENT3'||CHR(10)||'FROM SCM_ADM_LOOKUP_MASTER_DETAIL L'||CHR(10)||'WHERE L.LOOKUP_TYPE = ''END_CUSTOMER'' AND L.SEGMENT2 <> ''-'' AND L.VALID_YN = ''Y'' AND L.SEGMENT1 = ''40'''||CHR(10)||'UNION ALL'||CHR(10)||'SELECT DISTINCT A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, NVL(D.SEGMENT3, A.END_CUSTOMER)'||CHR(10)||'FROM SCM_MST_SITE A'||CHR(10)||'LEFT JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D'||CHR(10)||'  ON A.DIVISION_ID = D.SEGMENT1 AND A.END_CUSTOMER = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'''||CHR(10)||'WHERE A.END_CUSTOMER IS NOT NULL'||CHR(10)||'  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')'||CHR(10)||') ORDER BY DIVISION_ID, CODE', T.USE_YN = 'Y', T.CREATED_BY = 'admin', T.CREATION_DATE = TO_DATE('20260723193618','YYYYMMDDHH24MISS'), T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = TO_DATE('20260723193618','YYYYMMDDHH24MISS')
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('EndCustomerByDivision', 'DM', 'DMF0003 EndCustomerByDivision (AS-IS BigFilter/UP_FX 1:1)', 'SELECT DIVISION_ID, DEPT_ID, CODE, NAME FROM ('||CHR(10)||'SELECT DISTINCT A.DIVISION_ID, B.DEPT_ID, A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME'||CHR(10)||'FROM SCM_MST_SITE_ITEM A'||CHR(10)||'JOIN SCM_MST_SSO_USER_INFO B ON B.USER_ID = TRIM(REGEXP_SUBSTR(A.OWNER, ''[^,]+'', 1, 1))'||CHR(10)||'JOIN SCM_MST_SSO_DEPT_INFO C ON B.DEPT_ID = C.DEPT_ID'||CHR(10)||'LEFT JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D'||CHR(10)||'  ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'''||CHR(10)||'WHERE A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y'''||CHR(10)||'UNION'||CHR(10)||'SELECT L.SEGMENT1, NULL, L.SEGMENT2, L.SEGMENT3'||CHR(10)||'FROM SCM_ADM_LOOKUP_MASTER_DETAIL L'||CHR(10)||'WHERE L.LOOKUP_TYPE = ''END_CUSTOMER'' AND L.SEGMENT2 <> ''-'' AND L.VALID_YN = ''Y'' AND L.SEGMENT1 = ''40'''||CHR(10)||'UNION ALL'||CHR(10)||'SELECT DISTINCT A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, NVL(D.SEGMENT3, A.END_CUSTOMER)'||CHR(10)||'FROM SCM_MST_SITE A'||CHR(10)||'LEFT JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D'||CHR(10)||'  ON A.DIVISION_ID = D.SEGMENT1 AND A.END_CUSTOMER = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'''||CHR(10)||'WHERE A.END_CUSTOMER IS NOT NULL'||CHR(10)||'  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')'||CHR(10)||') ORDER BY DIVISION_ID, CODE', 'Y', 'admin', TO_DATE('20260723193618','YYYYMMDDHH24MISS'), 'admin', TO_DATE('20260723193618','YYYYMMDDHH24MISS'));

