WHEN MATCHED THEN UPDATE SET T.SQL_NM = 'DMF0082 End Customer by division (END_CUSTOMER lookup)', T.SQL_DTL_CTN = 'SELECT DISTINCT CODE, NAME FROM ('||CHR(10)||'  /* (1) END_CUSTOMER lookup axis - div 40 표기 원천 [E20260814-ENDCUST] */'||CHR(10)||'  SELECT L.SEGMENT2 AS CODE, NVL(L.SEGMENT3, L.SEGMENT2) AS NAME'||CHR(10)||'  FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L'||CHR(10)||'  WHERE  L.LOOKUP_TYPE = ''END_CUSTOMER'' AND L.VALID_YN = ''Y'' AND L.SEGMENT2 <> ''-'''||CHR(10)||'  AND    ( NVL(TRIM(@divisionId), ''-'') = ''-'' OR L.SEGMENT1 = TRIM(@divisionId) )'||CHR(10)||'  UNION ALL'||CHR(10)||'  /* (2) div 40 : SITE_ITEM owner axis (AS-IS EndCustomerByDivision40) */'||CHR(10)||'  SELECT A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME'||CHR(10)||'  FROM   SCM_MGR.SCM_MST_SITE_ITEM A'||CHR(10)||'  JOIN   SCM_MGR.SCM_MST_SSO_USER_INFO B ON B.USER_ID = TRIM(REGEXP_SUBSTR(A.OWNER, ''[^,]+'', 1, 1))'||CHR(10)||'  JOIN   SCM_MGR.SCM_MST_SSO_DEPT_INFO C ON C.DEPT_ID = B.DEPT_ID'||CHR(10)||'  LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D'||CHR(10)||'         ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2'||CHR(10)||'        AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'''||CHR(10)||'  WHERE  A.VALID_YN = ''Y'' AND TRIM(@divisionId) = ''40'' AND A.DIVISION_ID = ''40'''||CHR(10)||'  UNION ALL'||CHR(10)||'  /* (3) div 81/82 : 조회조건과 동일 축 = SCM_MST_SITE.END_CUSTOMER (AS-IS BigFilter'||CHR(10)||'         EndCustomerByDivision 의 비40 분기 원문과 동일) [E20260818-ENDCUST81] */'||CHR(10)||'  SELECT S.END_CUSTOMER AS CODE, NVL(D.SEGMENT3, S.END_CUSTOMER) AS NAME'||CHR(10)||'  FROM   SCM_MGR.SCM_MST_SITE S'||CHR(10)||'  LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D'||CHR(10)||'         ON D.SEGMENT1 = S.DIVISION_ID AND D.SEGMENT2 = S.END_CUSTOMER'||CHR(10)||'        AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y'''||CHR(10)||'  WHERE  S.END_CUSTOMER IS NOT NULL AND NVL(TRIM(@divisionId), ''-'') <> ''-'''||CHR(10)||'  AND    S.DIVISION_ID = TRIM(@divisionId) AND TRIM(@divisionId) <> ''40'''||CHR(10)||') ORDER BY NAME', T.USE_YN = 'Y', T.CREATED_BY = 'admin', T.CREATION_DATE = TO_DATE('20260814085449','YYYYMMDDHH24MISS'), T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = TO_DATE('20260818175330','YYYYMMDDHH24MISS')
