RIM(@divisionId) AND TRIM(@divisionId) <> ''40'''||CHR(10)||') ORDER BY NAME', 'Y', 'admin', TO_DATE('20260814085449','YYYYMMDDHH24MISS'), 'admin', TO_DATE('20260818175330','YYYYMMDDHH24MISS'));

