VALUES ('FcstTypeByUserGroupDMF0082', 'DM', 'DMF0082 FCST Type 표시용 (division 전달 시 W/S 분기 — AS-IS UP_FX_GetCommonDataList_DM)', 'SELECT CODE, NAME, DISPLAY_SEQ FROM ('||CHR(10)||'  /* [E20260814-WSDIV → E20260819-FCSTTYPE6] 81 계열 + DM Planner(W/S)'||CHR(10)||'     → SALES_TYPE_CODE2 ∪ SALES_TYPE_CODE2_ADD 6종 (2026-08-19 통합테스트 —'||CHR(10)||'     AS-IS DMF0003 FcstTypeEditMode 동형. 구 4종엔 CODE2_ADD(Recall/RMA) 누락) */'||CHR(10)||'  SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME'||CHR(10)||'       , CASE LOOKUP_TYPE WHEN ''SALES_TYPE_CODE2'' THEN DISPLAY_SEQ ELSE 100 + DISPLAY_SEQ END AS DISPLAY_SEQ'||CHR(10)||'  FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL'||CHR(10)||'  WHERE  LOOKUP_TYPE IN (''SALES_TYPE_CODE2'', ''SALES_TYPE_CODE2_ADD'')'||CHR(10)||'  AND    VALID_YN = ''Y'''||CHR(10)||'  AND    NVL(TRIM(@divisionId), ''-'') LIKE ''81%'''||CHR(10)||'  AND    EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M G'||CHR(10)||'                 WHERE G.USER_ID = @sesUserId AND G.USER_GR_ID = ''DM Planner (W/S)'' AND G.USE_YN = ''Y'')'||CHR(10)||'  UNION ALL'||CHR(10)||'  /* division 전달 + W/S 자격 아님 → SALES_TYPE_CODE 에서 전용플래그(ATTRIBUTE2=''Y'' — 실측 WS/WSF 2건 유일) 제외 = 12종 */'||CHR(10)||'  SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME, DISPLAY_SEQ'||CHR(10)||'  FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL'||CHR(10)||'  WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE'''||CHR(10)||'  AND    VALID_YN = ''Y'''||CHR(10)||'  AND    NVL(ATTRIBUTE2, '' '') <> ''Y'''||CHR(10)||'  AND    NVL(TRIM(@divisionId), ''-'') <> ''-'''||CHR(10)||'  AND    NOT ( NVL(TRIM(@divisionId), ''-'') LIKE ''81%'''||CHR(10)||'               AND EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M G'||CHR(10)||'                           WHERE G.USER_ID = @sesUserId AND G.USER_GR_ID = ''DM Planner (W/S)'' AND G.USE_YN = ''Y'') )'||CHR(10)||'  UNION ALL'||CHR(10)||'  /* division 미전달(메타 셀 콤보 = CODE->NAME 표시 매핑) → 전 코드 1행씩 (중복 없음) */'||CHR(10)||'  SELECT SEGMENT1 AS CODE, SEGMENT2 AS NAME, DISPLAY_SEQ'||CHR(10)||'  FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL'||CHR(10)||'  WHERE  LOOKUP_TYPE = ''SALES_TYPE_CODE'''||CHR(10)||'  AND    VALID_YN = ''Y'''||CHR(10)||'  AND    NVL(TRIM(@divisionId), ''-'') = ''-'''||CHR(10)||') ORDER BY DISPLAY_SEQ, CODE', 'Y', 'admin', TO_DATE('20260807192239','YYYYMMDDHH24MISS'), 'admin', TO_DATE('20260819234216','YYYYMMDDHH24MISS'));

